\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome5}
\pagestyle{empty}

% ── IPCC Custom Color Theme ──
% Deep navy + warm-to-hot accents per task brief
\definecolor{primary}{HTML}{0A1628}        % Deep navy (title bar, headers)
\definecolor{secondary}{HTML}{C0392B}      % Vermilion red (urgency, risks)
\definecolor{accent}{HTML}{D68910}         % Amber (warming, projections)
\definecolor{bgposter}{HTML}{F0EDE7}       % Warm institutional grey-tan
\definecolor{redbg}{HTML}{FDF3F2}          % Red-tinted card bg
\definecolor{bluebg}{HTML}{EEF0F6}         % Blue-tinted card bg
\definecolor{darkbg}{HTML}{F5F0EB}         % Warm cream card bg
\definecolor{amberbg}{HTML}{FFF9F0}        % Amber-tinted card bg
\definecolor{redtitlebg}{HTML}{FBE4E0}     % Red card title tint
\definecolor{bluetitlebg}{HTML}{DFE4EF}    % Blue card title tint
\definecolor{darktitlebg}{HTML}{EDE5DB}    % Dark card title tint
\definecolor{ambertitlebg}{HTML}{FFF0DD}   % Amber card title tint
\definecolor{textdark}{HTML}{17243A}       % Dark navy text
\definecolor{textgray}{HTML}{4B5563}       % Muted text
\definecolor{stathighlight}{HTML}{FEE8E8}  % Stat callout bg (warm)
\definecolor{statblue}{HTML}{E8F0FE}       % Stat callout bg (cool)
\definecolor{statamber}{HTML}{FFF4E4}      % Stat callout bg (amber)
\definecolor{titleaccent}{HTML}{E85D3A}    % Warm accent for title underline

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!15!white,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR (rows top-4, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30},
  borderline south={4pt}{0pt}{titleaccent}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{68}{82}\selectfont\bfseries Climate Change 2023}\\[8pt]
  {\fontsize{44}{54}\selectfont Key Findings from the IPCC Sixth Assessment Synthesis Report}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{white!70}%
  Intergovernmental Panel on Climate Change (IPCC) $\cdot$ AR6 Synthesis Report $\cdot$ March 2023}\\[6pt]
  {\fontsize{26}{32}\selectfont\color{white!55}%
  Contribution of Working Groups I, II, and III to the Sixth Assessment Report}
}

% ═══════════════════════════════════════════
% STAT BANNER — 7 Headline Metrics (rows 4-8, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2pt}{0pt}{primary!25},
]{name=stats, column=1, span=3, between=row4 and row8}{
  \centering

  % ── TOP ROW: 4 metrics ──
  \begin{minipage}[c]{0.240\linewidth}\centering
    \colorbox{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{secondary}\textbf{+1.1\textdegree C}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Global surface temperature}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}2011--2020 vs. 1850--1900}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.240\linewidth}\centering
    \colorbox{statblue}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary}\textbf{410 ppm}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Atmospheric CO\textsubscript{2}}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}Highest in 2 million years}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.240\linewidth}\centering
    \colorbox{statamber}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{accent}\textbf{$\sim$59 Gt}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Global GHG emissions}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}CO\textsubscript{2}-eq in 2019}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.240\linewidth}\centering
    \colorbox{statblue}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary}\textbf{$\sim$500 Gt}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Remaining carbon budget}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}For 1.5\textdegree C (50\% likelihood)}\vspace{6pt}%
    }}
  \end{minipage}

  \vspace{8pt}

  % ── BOTTOM ROW: 3 metrics (centered) ──
  \begin{minipage}[c]{0.310\linewidth}\centering
    \colorbox{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{secondary}\textbf{$-$43\% by 2030}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Required GHG reduction}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}Below 2019 levels for 1.5\textdegree C}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.310\linewidth}\centering
    \colorbox{statamber}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent}\textbf{+0.20 m}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}Global mean sea level rise}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}1901--2018; accelerating}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.310\linewidth}\centering
    \colorbox{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{secondary}\textbf{3.3--3.6 B}}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark}People highly vulnerable}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray}Exposed to severe climate hazards}\vspace{6pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════
% ROW A: Observed Changes | Future Projections | Risks & Impacts
% (rows 8-14, 6 rows)
% ═══════════════════════════════════════════

% ── Col 1: Observed Changes (rows 8-14) ──
\posterbox[bluecard, title={Observed Changes \& Current State}
]{name=observed, column=1, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \textbf{Every region on Earth is already affected} by human-caused climate change, with widespread and intensifying consequences.

  \vspace{4pt}
  \begin{itemize}[itemsep=6pt]
    \item \textbf{+1.1\textdegree C} global surface temperature rise since pre-industrial period

    \item \textbf{$\sim$40\% loss} in Arctic September sea ice area (1979--2020)

    \item \textbf{$\sim$0.20 m} global mean sea level rise (1901--2018); rate accelerating

    \item Frequency \& intensity of heatwaves, heavy precipitation, droughts, and tropical cyclones increasing globally
  \end{itemize}

  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\bfseries
    Atmospheric CO\textsubscript{2} at 410 ppm in 2019 -- highest in at least 2 million years
  }}

  \vspace{4pt}
  {\fontsize{26}{32}\selectfont\color{textgray}
  \renewcommand{\arraystretch}{1.4}
  \begin{tabular}{@{}lll@{}}
  \rowcolor{primary!12} \textbf{Indicator} & \textbf{Value} & \textbf{Period} \\
  Surface temp. rise & +1.1\textdegree C & 2011--2020 \\
  Atmospheric CO\textsubscript{2} & 410 ppm & 2019 \\
  Global GHG emissions & $\sim$59 GtCO\textsubscript{2}e & 2019 \\
  Sea level rise & $\sim$0.20 m & 1901--2018 \\
  Arctic sea ice loss & $\sim$40\% area & 1979--2020 \\
  \end{tabular}
  }
}

% ── Col 2: Future Projections (rows 8-14) ──
\posterbox[ambercard, title={Future Projections: SSP Scenarios}
]{name=projections, column=2, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \textbf{Global warming trajectories diverge sharply} depending on near-term policy choices. Under current policies, warming could exceed \textbf{2.7\textdegree C by 2100}.

  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{textgray}\renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}lcc@{}}
  \rowcolor{primary!12} \textbf{Scenario} & \textbf{Warming by 2100} & \textbf{Pathway} \\
  SSP1-1.9 & $\sim$1.4\textdegree C & Sustainability \\
  SSP1-2.6 & $\sim$1.8\textdegree C & Low emissions \\
  SSP2-4.5 & $\sim$2.7\textdegree C & Intermediate \\
  SSP3-7.0 & $\sim$3.6\textdegree C & High emissions \\
  SSP5-8.5 & $\sim$4.4\textdegree C & Fossil-intensive \\
  \end{tabular}
  }

  \vspace{6pt}

  % SSP scenario visual strip
  \colorbox{primary!8}{\parbox{0.94\linewidth}{%
    \centering\fontsize{26}{32}\selectfont\bfseries\color{primary} Warming Trajectory by Scenario\\[4pt]
    \fontsize{24}{30}\selectfont\color{textdark}
    \begin{minipage}{0.95\linewidth}\centering
    \colorbox{bluebg}{\rule{0pt}{18pt}\hspace{4pt}SSP1-1.9: $\sim$1.4\textdegree C \hspace{12pt}}
    \colorbox{bluebg!70}{\rule{0pt}{18pt}\hspace{4pt}SSP1-2.6: $\sim$1.8\textdegree C \hspace{12pt}}
    \colorbox{amberbg}{\rule{0pt}{18pt}\hspace{4pt}SSP2-4.5: $\sim$2.7\textdegree C \hspace{12pt}}
    \colorbox{redbg}{\rule{0pt}{18pt}\hspace{4pt}SSP3-7.0: $\sim$3.6\textdegree C \hspace{12pt}}
    \colorbox{redtitlebg}{\rule{0pt}{18pt}\hspace{4pt}SSP5-8.5: $\sim$4.4\textdegree C}
    \end{minipage}
  }}

  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\bfseries
    Sea level rise: 0.28--1.01 m by 2100, continuing for centuries regardless of pathway
  }}
}

% ── Col 3: Risks & Vulnerabilities (rows 8-14) ──
\posterbox[redcard, title={Risks, Vulnerabilities \& Cascading Impacts}
]{name=risks, column=3, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \textbf{3.3--3.6 billion people} live in contexts highly vulnerable to climate change. Climate hazards interact with poverty, inequality, and ecosystem degradation to produce compounding risks.

  \vspace{4pt}
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Food security:} Crop yield growth slowing; tropical fisheries productivity declining

    \item \textbf{Water stress:} Over half the global population experiences severe water scarcity $\geq$1 month/year

    \item \textbf{Health:} Heat-related mortality and vector-borne disease ranges expanding

    \item \textbf{Biodiversity:} Up to \textbf{14\% of terrestrial species} face very high extinction risk at 1.5\textdegree C; risk escalates sharply beyond
  \end{itemize}

  \vspace{4pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\bfseries\color{secondary}
    Risks cascade across sectors and regions. Beyond 1.5\textdegree C, adaptation limits are increasingly exceeded.
  }}
}

% ═══════════════════════════════════════════
% ROW B: Mitigation Pathways | The Narrowing Window
% (rows 14-19, 5 rows)
% ═══════════════════════════════════════════

% ── Col 1+2 (span=2): Mitigation & Adaptation (rows 14-19) ──
\posterbox[bluecard, title={Mitigation and Adaptation Pathways}
]{name=mitigation, column=1, span=2, between=row14 and row19}{
  \fontsize{30}{40}\selectfont
  \begin{minipage}[t]{0.48\linewidth}
    \textbf{Emissions Reduction Requirements}\\[4pt]
    \begin{itemize}[itemsep=6pt]
      \item \textbf{1.5\textdegree C pathway:} $-$43\% GHG by 2030; \textbf{net zero CO\textsubscript{2} by $\sim$2050}

      \item \textbf{2\textdegree C pathway:} $-$27\% GHG by 2030; \textbf{net zero CO\textsubscript{2} by $\sim$2070}

      \item Remaining carbon budget for 1.5\textdegree C (50\% chance): \textbf{$\sim$500 GtCO\textsubscript{2}} from 2020
    \end{itemize}

    \vspace{4pt}
    \colorbox{primary!22}{\parbox{0.94\linewidth}{%
      \centering\fontsize{26}{34}\selectfont\bfseries
      Climate finance falls short by a factor of \textbf{3--6$\times$} for adaptation alone.
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \textbf{Key Mitigation Levers}\\[4pt]
    \begin{itemize}[itemsep=6pt]
      \item Rapid decarbonization of energy systems

      \item Electrification of transport and industry

      \item Demand-side efficiency improvements

      \item Protection and restoration of carbon sinks (forests, oceans, soils)

      \item Carbon dioxide removal (CDR) to counterbalance residual emissions
    \end{itemize}

    \vspace{4pt}
    \colorbox{accent!20}{\parbox{0.94\linewidth}{%
      \centering\fontsize{26}{34}\selectfont\bfseries
      Immediate, deep \& sustained reductions across \textbf{all sectors} are essential.
    }}
  \end{minipage}
}

% ── Col 3: The Narrowing Window (rows 14-19) ──
\posterbox[highlightcard, title={The Narrowing Window for Action}
]{name=urgency, column=3, between=row14 and row19}{
  \fontsize{30}{40}\selectfont
  \textbf{The choices made this decade} will determine whether warming can be held to 1.5\textdegree C or 2\textdegree C.

  \vspace{6pt}
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Delayed action increases costs,} locks in high-carbon infrastructure, and reduces the feasibility of limiting warming

    \item \textbf{Current policies} put the world on track for $\sim$2.7\textdegree C of warming by 2100 -- far above Paris Agreement goals

    \item \textbf{Every increment of warming matters.} Limiting warming to 1.5\textdegree C rather than 2\textdegree C substantially reduces risks to human and natural systems
  \end{itemize}

  \vspace{8pt}
  \colorbox{white!70}{\parbox{0.94\linewidth}{%
    \centering\vspace{4pt}
    {\fontsize{32}{40}\selectfont\bfseries\color{secondary}
    The window is rapidly closing.}\\[4pt]
    {\fontsize{26}{34}\selectfont\color{textdark}
    Immediate, deep, and sustained emissions reductions across all sectors are essential to secure a liveable and sustainable future for all.}\vspace{4pt}
  }}
}

% ═══════════════════════════════════════════
% FOOTER: Sources (rows 19-bottom, 1 row, span=3)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white!80,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=footer, column=1, span=3, between=row19 and bottom}{
